import { getNotificationPreference, toggleNotificationPreference } from './actions'

export default async function Home() {
  // Simulate a user ID (in a real app, get this from authentication)
  const userId = 'user-123'

  // Fetch the current notification preference
  const isNotificationEnabled = await getNotificationPreference(userId)

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Settings</h1>

      <div style={{ marginTop: '2rem' }}>
        <h2>Notification Preferences</h2>
        <p>Current status: <strong>{isNotificationEnabled ? 'ON' : 'OFF'}</strong></p>

        <form action={toggleNotificationPreference.bind(null, userId)}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              fontSize: '1rem',
              cursor: 'pointer',
              backgroundColor: isNotificationEnabled ? '#dc2626' : '#16a34a',
              color: 'white',
              border: 'none',
              borderRadius: '0.25rem'
            }}
          >
            Turn {isNotificationEnabled ? 'OFF' : 'ON'}
          </button>
        </form>
      </div>
    </main>
  );
}

